import type { Request } from 'express';

/** A user as returned to the client (never includes the password hash). */
export interface PublicUser {
  id: string;
  email: string;
  display_name: string;
  avatar_color: string;
  created_at: number;
  last_seen_at: number | null;
}

/** Full user row as stored in the DB. */
export interface UserRow extends PublicUser {
  password_hash: string;
}

export interface SessionRow {
  token: string;
  user_id: string;
  created_at: number;
  expires_at: number;
}

export interface ChannelRow {
  id: string;
  name: string;
  is_direct: number;
  created_by: string | null;
  created_at: number;
}

export interface MessageRow {
  id: string;
  channel_id: string;
  user_id: string;
  body: string;
  created_at: number;
  edited_at: number | null;
  deleted_at: number | null;
}

/** Express request augmented by the `requireAuth` middleware. */
export interface AuthedRequest extends Request {
  user?: PublicUser;
  sessionToken?: string;
}

import { randomBytes, scryptSync, timingSafeEqual } from 'node:crypto';

/**
 * Hash a password using Node's built-in scrypt.
 * Stored format: `${saltHex}:${hashHex}`
 */
export function hashPassword(password: string): string {
  const salt = randomBytes(16).toString('hex');
  const hash = scryptSync(password, salt, 64).toString('hex');
  return `${salt}:${hash}`;
}

/** Verify a plaintext password against a stored `salt:hash` string. */
export function verifyPassword(password: string, stored: string): boolean {
  const [salt, hash] = stored.split(':');
  if (!salt || !hash) return false;
  const computed = scryptSync(password, salt, 64);
  const expected = Buffer.from(hash, 'hex');
  return computed.length === expected.length && timingSafeEqual(computed, expected);
}

